// Swift conveniences over the generated engine API (qcalc_ffi.swift, regenerated by native/scripts/build-mac.sh;
// don't edit that file). Each `…Async` call here makes its own CancelToken and cancels it when the calling Task
// is cancelled, so `task.cancel()` stops the Rust work at its next checkpoint and the call throws
// CoreError.Cancelled.

import Foundation

extension Engine {
    /// Runs `body` with a fresh token that the current Task's cancellation cancels.
    private func withCancelToken<T>(_ body: (CancelToken) async throws -> T) async throws -> T {
        let token = CancelToken()
        return try await withTaskCancellationHandler {
            // already cancelled: the engine answers CoreError.Cancelled without starting
            if Task.isCancelled { token.cancel() }
            return try await body(token)
        } onCancel: {
            token.cancel()
        }
    }

    /// `liveAsync(request:cancel:)`, cancelled with the calling Task.
    public func liveAsync(request: LiveRequest) async throws -> LiveAnswer {
        try await withCancelToken { try await liveAsync(request: request, cancel: $0) }
    }

    /// `evaluateAsync(lines:options:cancel:)`, cancelled with the calling Task.
    public func evaluateAsync(lines: [String], options: EvalOptions) async throws -> [LineAnswer] {
        try await withCancelToken { try await evaluateAsync(lines: lines, options: options, cancel: $0) }
    }

    /// `graphAsync(input:options:settings:cancel:)`, cancelled with the calling Task.
    public func graphAsync(input: String, options: GraphOptions, settings: EvalOptions) async throws -> GraphResult? {
        try await withCancelToken { try await graphAsync(input: input, options: options, settings: settings, cancel: $0) }
    }

    /// `closedForm(jobJson:cancel:)`, cancelled with the calling Task.
    public func closedForm(jobJson: String) async throws -> String? {
        try await withCancelToken { try await closedForm(jobJson: jobJson, cancel: $0) }
    }
}

extension Span {
    /// The span as an `NSRange` over the input (both count UTF-16 units).
    public var nsRange: NSRange { NSRange(location: Int(start), length: Int(end) - Int(start)) }
}

extension TextSpan {
    public var nsRange: NSRange { NSRange(location: Int(start), length: Int(end) - Int(start)) }
}

extension HistoryView {
    /// The view the settings start with (recent rows, exact answers) at `now`.
    public static func standard(sigFigs: UInt32 = 6, now: Date = Date()) -> HistoryView {
        HistoryView(show: .recent, answerForm: .exact, sigFigs: sigFigs, nowMs: Int64(now.timeIntervalSince1970 * 1000))
    }
}
